import { availableCopies } from "./store.mjs";

const byTitle = (a, b) => a.title.toLowerCase().localeCompare(b.title.toLowerCase());

// query: { q, author, tag, yearFrom, yearTo, available, sort, page = 1, pageSize = 10 }
// Returns { items, total, page, pages }.
export function search(store, query = {}) {
  const page = query.page ?? 1;
  const pageSize = query.pageSize ?? 10;
  const words = (query.q ?? "").toLowerCase().split(/\s+/).filter(Boolean);
  const author = query.author?.toLowerCase();

  const matches = store.books.filter((b) => {
    const hay = `${b.title} ${b.author}`.toLowerCase();
    if (!words.every((w) => hay.includes(w))) return false;
    if (author !== undefined && b.author.toLowerCase() !== author) return false;
    if (query.tag !== undefined && !b.tags.includes(query.tag)) return false;
    if (query.yearFrom != null && b.year < query.yearFrom) return false;
    if (query.yearTo != null && b.year > query.yearTo) return false;
    if (query.available === true && availableCopies(store, b.id) <= 0) return false;
    return true;
  });

  matches.sort(query.sort === "year" ? (a, b) => b.year - a.year || byTitle(a, b) : byTitle);

  const total = matches.length;
  const items = matches.slice((page - 1) * pageSize, page * pageSize);
  return { items, total, page, pages: Math.ceil(total / pageSize) };
}
