import { addBook } from "./store.mjs";

const field = (v) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(field).join(","));
  }
  return lines.join("\n") + "\n";
}

// Splits text into records of fields, each with the 1-based line it starts on.
function parse(text) {
  const records = [];
  let row = [];
  let cur = "";
  let quoted = false;
  let line = 1;
  let start = 1;
  const endRecord = () => {
    row.push(cur);
    records.push({ line: start, fields: row });
    row = [];
    cur = "";
    start = line;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { cur += '"'; i++; } else quoted = false;
      } else {
        if (c === "\n") line++;
        cur += c;
      }
    } else if (c === '"') {
      quoted = true;
    } else if (c === ",") {
      row.push(cur);
      cur = "";
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      line++;
      endRecord();
    } else {
      cur += c;
    }
  }
  if (cur !== "" || row.length) endRecord();
  return records;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const records = parse(text);
  const errors = [];
  let added = 0;
  if (!records.length) return { added, errors };
  const cols = records[0].fields.map((h) => h.trim());
  const idx = (name) => cols.indexOf(name);
  for (const { line, fields } of records.slice(1)) {
    if (fields.length === 1 && fields[0].trim() === "") continue;
    const get = (name) => {
      const i = idx(name);
      return i < 0 ? "" : (fields[i] ?? "").trim();
    };
    const title = get("title");
    const author = get("author");
    const yearText = get("year");
    const copiesText = get("copies");
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!WHOLE.test(yearText)) message = "year must be a whole number";
    else if (copiesText !== "" && (!/^\d+$/.test(copiesText) || Number(copiesText) < 1)) {
      message = "copies must be a positive whole number";
    }
    if (message) {
      errors.push({ line, message });
      continue;
    }
    const tags = get("tags");
    addBook(store, {
      title,
      author,
      year: Number(yearText),
      tags: tags === "" ? [] : tags.split(";"),
      copies: copiesText === "" ? 1 : Number(copiesText),
    });
    added++;
  }
  return { added, errors };
}
