import { daysBetween } from "./dates.mjs";
import { getBook, getMember } from "./store.mjs";

export function overdueReport(store, asOf) {
  return store.loans
    .filter((l) => !l.returned && l.due < asOf)
    .map((l) => ({
      loanId: l.id,
      bookId: l.bookId,
      title: getBook(store, l.bookId)?.title ?? null,
      memberId: l.memberId,
      memberName: getMember(store, l.memberId)?.name ?? null,
      daysOverdue: daysBetween(l.due, asOf),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue || (a.loanId < b.loanId ? -1 : a.loanId > b.loanId ? 1 : 0));
}

export function popularBooks(store, { from, to, limit = 5 } = {}) {
  const counts = new Map();
  for (const l of store.loans) {
    if (l.out >= from && l.out <= to) counts.set(l.bookId, (counts.get(l.bookId) ?? 0) + 1);
  }
  return [...counts]
    .map(([bookId, loans]) => ({ bookId, title: getBook(store, bookId)?.title ?? "", loans }))
    .sort((a, b) => b.loans - a.loans || (a.title < b.title ? -1 : a.title > b.title ? 1 : 0))
    .slice(0, limit);
}

export function memberActivity(store, memberId) {
  const loans = store.loans.filter((l) => l.memberId === memberId);
  let lastOut = null;
  for (const l of loans) if (lastOut === null || l.out > lastOut) lastOut = l.out;
  return {
    memberId,
    totalLoans: loans.length,
    openLoans: loans.filter((l) => !l.returned).length,
    lastOut,
  };
}
